-- Verified fertiliser catalogue, sourced 2026-10-31. Generated from the suppliers' published analyses.
-- Re-running is safe: existing entries (same supplier and name) are left alone.

INSERT INTO catalogue_sources (id, name, url, coverage, retrieved_on, notes) VALUES
  ('ballance-range', 'Ballance Agri-Nutrients product range', 'https://ballance.co.nz/Fertiliser-Products/c/All-Product-Ranges',
   'All 94 products listed on the range page on the retrieval date, with N, P, K, S, Mg and Ca as published', '2026-10-31',
   'Elemental percentages as shown by Ballance. Prices and availability are not stored.'),
  ('ravensdown-labels', 'Ravensdown product labels', 'https://www.ravensdown.co.nz',
   'Only Ravensdown fertilisers whose label PDF could be read: N-Protect, Granular Ammonium Sulphate, Cropmaster 15', '2026-10-31',
   'The Ravensdown website blocks automated access, so most of its range is not yet in the catalogue. Add products from a Ravensdown label as farm-entered, or update the catalogue from their product list.')
ON CONFLICT (id) DO UPDATE SET coverage = EXCLUDED.coverage, retrieved_on = EXCLUDED.retrieved_on, notes = EXCLUDED.notes;

